"use client";
import { TinyLineChart } from "@/components/application/selene/tiny-line-chart";

const card = { borderRadius: 16, color: "light-dark(#1a1a1c, #ececee)", background: "light-dark(#fff, #1c1c1f)", boxShadow: "0 0 0 1px light-dark(rgb(0 0 0 / 0.06), rgb(255 255 255 / 0.09)), 0 2px 8px rgb(0 0 0 / 0.04)" } as const;
const muted = "light-dark(#71717a, #a1a1aa)";

function StatTile() {
  return (
    <div style={{ ...card, display: "grid", gap: 10, width: 220, padding: "16px 16px 14px" }}>
      <span style={{ fontSize: 12, color: muted }}>Revenue</span>
      <span style={{ fontSize: 22, fontWeight: 600, letterSpacing: "-0.02em", fontVariantNumeric: "tabular-nums" }}>$48,210</span>
      <TinyLineChart data={[9, 14, 8, 17, 11, 19, 10, 16, 21, 12, 20, 15]} width={188} height={46} color="#0f8a7e" fill easing="ease" />
    </div>
  );
}

const ROWS = [
  { label: "Visitors", value: "12.4k", data: [4, 6, 5, 8, 7, 9, 8, 11, 10, 13] },
  { label: "Signups", value: "318", data: [3, 2, 4, 3, 5, 4, 6, 5, 7, 8] },
  { label: "Churn", value: "1.2%", data: [8, 7, 9, 6, 7, 5, 6, 4, 5, 4] },
];

function ListRows() {
  return (
    <div style={{ ...card, display: "grid", width: 240, padding: "6px 16px" }}>
      {ROWS.map((r) => (
        <div key={r.label} style={{ display: "grid", gridTemplateColumns: "1fr auto 48px", alignItems: "center", gap: 12, padding: "9px 0", fontSize: 13 }}>
          <span>{r.label}</span>
          <TinyLineChart data={r.data} size="s" color="#3b5bdb" />
          <span style={{ textAlign: "right", color: muted, fontVariantNumeric: "tabular-nums" }}>{r.value}</span>
        </div>
      ))}
    </div>
  );
}

function Inline() {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 13, color: "light-dark(#1a1a1c, #ececee)" }}>
      <span style={{ color: muted }}>Response time</span>
      <TinyLineChart data={[6, 9, 7, 11, 8, 6, 9, 5, 7, 4]} width={64} height={20} color="#6d4aff" />
      <span style={{ fontWeight: 600, fontVariantNumeric: "tabular-nums" }}>142ms</span>
    </div>
  );
}

export default function TinyLineChartDemo({ variant = "overview" }: { variant?: string }) {
  if (variant === "stat-tile") return <StatTile />;
  if (variant === "list") return <ListRows />;
  if (variant === "inline") return <Inline />;
  return (
    <div style={{ display: "grid", gap: 16, justifyItems: "center" }}>
      <StatTile />
      <ListRows />
    </div>
  );
}

